PRAGMA foreign_keys=ON;
CREATE TABLE app_settings(id INTEGER PRIMARY KEY CHECK(id=1),setup_completed INTEGER NOT NULL DEFAULT 0 CHECK(setup_completed IN(0,1)),instance_name TEXT NOT NULL,user_management_mode TEXT NOT NULL DEFAULT 'OWNER_ONLY' CHECK(user_management_mode IN('OWNER_ONLY','DELEGATED')),registration_mode TEXT NOT NULL DEFAULT 'CLOSED' CHECK(registration_mode IN('CLOSED','INVITE_ONLY','OPEN_REGULAR','OPEN_GUEST','OPEN_BOTH')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL) STRICT;
CREATE TABLE profile_fields(id TEXT PRIMARY KEY,field_key TEXT NOT NULL UNIQUE,label TEXT NOT NULL,data_type TEXT NOT NULL CHECK(data_type IN('TEXT','DATE','EMAIL','INTEGER','BOOLEAN')),regular_requirement TEXT NOT NULL CHECK(regular_requirement IN('HIDDEN','OPTIONAL','REQUIRED')),guest_requirement TEXT NOT NULL CHECK(guest_requirement IN('HIDDEN','OPTIONAL','REQUIRED')),show_optional_during_registration INTEGER NOT NULL DEFAULT 0 CHECK(show_optional_during_registration IN(0,1)),max_length INTEGER CHECK(max_length IS NULL OR max_length BETWEEN 1 AND 4000),sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL) STRICT;
CREATE TABLE objects(id TEXT PRIMARY KEY,type TEXT NOT NULL CHECK(type IN('USER','SPACE','GROUP','ROLE','SYSTEM')),subtype TEXT,name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 200),description TEXT,status TEXT,created_by_user_id TEXT REFERENCES objects(id) ON DELETE SET NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK((type='SPACE' AND subtype IN('PRIVATE','FAMILY','ORGANIZATION')) OR (type<>'SPACE' AND subtype IS NULL)),CHECK((type='USER' AND status IS NULL) OR(type<>'USER' AND status IN('ACTIVE','DISABLED','ARCHIVED')))) STRICT;
CREATE TABLE users(object_id TEXT PRIMARY KEY REFERENCES objects(id) ON DELETE CASCADE,account_kind TEXT NOT NULL CHECK(account_kind IN('REGULAR','GUEST')),username TEXT NOT NULL COLLATE NOCASE UNIQUE CHECK(length(username) BETWEEN 3 AND 50),email TEXT COLLATE NOCASE UNIQUE,first_name TEXT,last_name TEXT,date_of_birth TEXT,fsk_limit INTEGER CHECK(fsk_limit IS NULL OR fsk_limit IN(0,6,12,16,18)),password_hash TEXT,mfa_secret_encrypted TEXT,mfa_enabled INTEGER NOT NULL DEFAULT 0 CHECK(mfa_enabled IN(0,1)),preferred_auth_method TEXT NOT NULL CHECK(preferred_auth_method IN('PASSKEY','PASSWORD_MFA')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK(preferred_auth_method<>'PASSWORD_MFA' OR(password_hash IS NOT NULL AND mfa_enabled=1))) STRICT;
CREATE TABLE user_profile_values(user_id TEXT NOT NULL REFERENCES users(object_id) ON DELETE CASCADE,field_id TEXT NOT NULL REFERENCES profile_fields(id) ON DELETE CASCADE,value_text TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(user_id,field_id)) WITHOUT ROWID,STRICT;
CREATE TABLE passkeys(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(object_id) ON DELETE CASCADE,credential_id BLOB NOT NULL UNIQUE,public_key BLOB NOT NULL,sign_count INTEGER NOT NULL DEFAULT 0,transports_json TEXT NOT NULL DEFAULT '[]',name TEXT NOT NULL,created_at TEXT NOT NULL,last_used_at TEXT,revoked_at TEXT) STRICT;
CREATE TABLE systems(id TEXT PRIMARY KEY REFERENCES objects(id) ON DELETE CASCADE,domain TEXT NOT NULL UNIQUE COLLATE NOCASE,allowed_origin TEXT NOT NULL UNIQUE COLLATE NOCASE,certificate_mode TEXT NOT NULL DEFAULT 'PUBLIC_TLS' CHECK(certificate_mode IN('PUBLIC_TLS','MTLS')),client_certificate_fingerprint TEXT,api_key_hash TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK(certificate_mode<>'MTLS' OR client_certificate_fingerprint IS NOT NULL)) STRICT;
CREATE TABLE system_permissions(id TEXT PRIMARY KEY,system_id TEXT NOT NULL REFERENCES systems(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT,status TEXT NOT NULL CHECK(status IN('ACTIVE','DISABLED','ARCHIVED')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(system_id,name COLLATE NOCASE)) STRICT;
CREATE TABLE system_user_fields(system_id TEXT NOT NULL REFERENCES systems(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(object_id) ON DELETE CASCADE,field_key TEXT NOT NULL,allowed INTEGER NOT NULL CHECK(allowed IN(0,1)),granted_by_user_id TEXT NOT NULL REFERENCES users(object_id) ON DELETE RESTRICT,updated_at TEXT NOT NULL,PRIMARY KEY(system_id,user_id,field_key)) WITHOUT ROWID,STRICT;
CREATE TABLE assignments(id TEXT PRIMARY KEY,source_object_id TEXT NOT NULL REFERENCES objects(id) ON DELETE CASCADE,target_object_id TEXT REFERENCES objects(id) ON DELETE CASCADE,target_permission_id TEXT REFERENCES system_permissions(id) ON DELETE CASCADE,relation TEXT NOT NULL CHECK(relation IN('MEMBER_OF','ASSIGNED_TO')),access TEXT NOT NULL CHECK(access IN('READ','READ_WRITE')),answer TEXT NOT NULL CHECK(answer IN('REQUESTED','ACCEPTED','DECLINED','CANCELLED')),requested_by_user_id TEXT NOT NULL REFERENCES users(object_id) ON DELETE RESTRICT,requested_at TEXT NOT NULL,answered_by_user_id TEXT REFERENCES users(object_id) ON DELETE SET NULL,answered_at TEXT,answer_message TEXT,updated_at TEXT NOT NULL,CHECK((target_object_id IS NOT NULL)<>(target_permission_id IS NOT NULL)),CHECK(target_object_id IS NULL OR source_object_id<>target_object_id)) STRICT;
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(object_id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,csrf_token TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,revoked_at TEXT) STRICT;
CREATE TABLE user_setups(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(object_id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,completed_at TEXT,failed_attempts INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL) STRICT;
CREATE TABLE invitations(id TEXT PRIMARY KEY,invited_email TEXT,account_kind TEXT NOT NULL CHECK(account_kind IN('REGULAR','GUEST')),token_hash TEXT NOT NULL UNIQUE,invited_by_user_id TEXT NOT NULL REFERENCES users(object_id) ON DELETE RESTRICT,expires_at TEXT NOT NULL,accepted_at TEXT,declined_at TEXT,revoked_at TEXT,created_at TEXT NOT NULL) STRICT;
CREATE INDEX ix_objects_type ON objects(type);CREATE INDEX ix_assignments_source ON assignments(source_object_id);CREATE INDEX ix_permissions_system ON system_permissions(system_id);CREATE INDEX ix_system_domain ON systems(domain);
